PAYLOAD = {'site.js': '', 'assets/az-photo-logo-approved-v1.png': ''}
EXPECTED_SITE_JS = '190dba2936bc2def347a43e94b81e6fe226ee77ae38220db9e4790a17c355361'

from pathlib import Path
import os, sys, re, base64, hashlib, json, shutil, tempfile, fcntl
from datetime import datetime, timezone
ROOT=Path('/var/www/azmednsk-preview')
BACKUPS=Path('/var/backups/azmednsk')
if len(sys.argv)==3 and sys.argv[1]=='--test-root':
    ROOT=Path(sys.argv[2]).resolve()
    if not str(ROOT).startswith('/tmp/az-watermark-test-'): raise SystemExit('STOP=Invalid test root')
    BACKUPS=ROOT.parent/(ROOT.name+'-backups')
elif len(sys.argv)!=1: raise SystemExit('STOP=Unexpected arguments')
def sha(b): return hashlib.sha256(b).hexdigest()
def safe(rel):
    p=ROOT/rel
    if p.is_symlink() or not p.resolve().is_relative_to(ROOT.resolve()): raise SystemExit('STOP=Unsafe path '+rel)
    return p
if not ROOT.is_dir() or ROOT.is_symlink(): raise SystemExit('STOP=Root invalid')
lock=open('/tmp/az-photo-watermark-v1.lock','w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
assets={k:base64.b64decode(v,validate=True) for k,v in PAYLOAD.items()}
site=safe('site.js'); current=site.read_bytes()
if sha(current)!=EXPECTED_SITE_JS and current!=assets['site.js']: raise SystemExit('STOP=site.js changed; recheck required')
version='az-logo-20261115-v1'
rx=re.compile(rb'(<script\b[^>]*\bsrc\s*=\s*["\x27])(/site\.js)(?:\?[^"\x27]*)?(["\x27])',re.I)
changes={}; before={}; pages=0
for p in sorted(ROOT.rglob('*.html')):
    rel=p.relative_to(ROOT).as_posix()
    if any(x in ('.git','assets','node_modules','backups') for x in p.relative_to(ROOT).parts): continue
    safe(rel)
    b=p.read_bytes()
    if not re.search(rb'<html\b',b,re.I):continue
    if b'azPhotoBrandingV1' in b: raise SystemExit('STOP=Unexpected inline branding '+rel)
    n=rx.sub(lambda m:m[1]+m[2]+b'?v='+version.encode()+m[3],b)
    if rx.search(b): pages+=1
    elif re.search(rb'<img\b',b,re.I):
        if len(re.findall(rb'</body\s*>',b,re.I))!=1: raise SystemExit('STOP=Unsupported HTML '+rel)
        n=re.sub(rb'</body\s*>',b'<script defer src="/site.js?v='+version.encode()+b'"></script></body>',b,flags=re.I);pages+=1
    if n!=b:
        # Photo markup remains byte-for-byte untouched.
        if re.findall(rb'<img\b[^>]*>',n,re.I)!=re.findall(rb'<img\b[^>]*>',b,re.I):raise SystemExit('STOP=Photo markup changed')
        changes[rel]=n;before[rel]=b
for rel,b in assets.items():
    p=safe(rel);old=p.read_bytes() if p.exists() else None
    if old!=b:
        if rel!='site.js' and old is not None:raise SystemExit('STOP=Asset collision '+rel)
        changes[rel]=b;before[rel]=old
if pages<4:raise SystemExit('STOP=Unexpected page count')
if not changes:
    print('PHOTO_LOGOS=ALREADY_INSTALLED; ORIGINAL_PHOTOS=UNCHANGED');sys.exit(0)
print('PREFLIGHT=PASS; PAGES='+str(pages)+'; ORIGINAL_PHOTOS=UNCHANGED',flush=True)
stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
backup=BACKUPS/('photo-logos-'+stamp);backup.mkdir(parents=True,exist_ok=False)
manifest={rel:{'before':sha(before[rel]) if before[rel] is not None else None,'after':sha(b)} for rel,b in changes.items()}
for rel,b in before.items():
    if b is not None:
        dst=backup/rel;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(safe(rel),dst)
(backup/'manifest.json').write_text(json.dumps(manifest,indent=2))
def write(rel,b):
    p=safe(rel);p.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.az-brand-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(b);f.flush();os.fsync(f.fileno())
        if p.exists():
            st=p.stat();shutil.copystat(p,tmp);os.chown(tmp,st.st_uid,st.st_gid)
        else:os.chmod(tmp,0o644)
        os.replace(tmp,p)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
# Assets first, then cache-versioned HTML. Never rewrite photos.
order=sorted(changes,key=lambda x:(x.endswith('.html'),x=='site.js',x));done=[]
try:
    for rel in order:
        p=safe(rel);now=p.read_bytes() if p.exists() else None
        if now!=before[rel]:raise RuntimeError('Concurrent change: '+rel)
        write(rel,changes[rel]);done.append(rel)
    for rel,b in changes.items():
        if safe(rel).read_bytes()!=b:raise RuntimeError('Readback mismatch: '+rel)
except Exception:
    for rel in reversed(done):
        if safe(rel).read_bytes()!=changes[rel]:continue
        if before[rel] is None:safe(rel).unlink()
        else:write(rel,before[rel])
    raise
print('PHOTO_LOGOS=PASS; APPROVED_LOGO=EXACT; ORIGINAL_PHOTOS=UNCHANGED')
print('AUTO_NEW_PHOTOS=YES; ICONS_QR_CERTIFICATES=EXCLUDED')
print('PAGES='+str(pages)+'; LOGO_BYTES='+str(len(assets['assets/az-photo-logo-approved-v1.png'])))
print('BACKUP='+str(backup))
print('URL=https://azmednsk.ru/team/')
